<script setup lang="ts">
definePageMeta({ role: 'admin', layout: 'admin' })

type ScheduleRow = { id: string; doctorId: string; scheduleDate: string; startTime: string; endTime: string; quota: number; isActive: boolean; doctor?: { id: string; fullName: string; specialization?: string | null } }
const modalOpen = ref(false)
const editMode = ref<'create' | 'edit'>('create')
const activeId = ref('')
const saving = ref(false)
const deletingId = ref('')
const selectedDoctorId = ref('')
const errorMessage = ref('')
const successMessage = ref('')
const form = reactive({ doctorId: '', scheduleDate: new Date().toISOString().split('T')[0], startTime: '08:00', endTime: '12:00', quota: 20, isActive: true })
const { data, pending, error, refresh } = await useFetch('/api/admin/schedules')
const { data: doctorsData } = await useFetch('/api/admin/doctors')
const rows = computed(() => (data.value?.data ?? []) as ScheduleRow[])
const doctorOptions = computed(() => ((doctorsData.value?.data ?? []) as any[]).map((item) => ({ label: item.fullName, value: item.id })))
const filteredRows = computed(() => rows.value.filter((row) => !selectedDoctorId.value || row.doctor?.id === selectedDoctorId.value))
function formatDate(value: string){ return new Date(value).toLocaleDateString('id-ID') }
function resetForm(){ Object.assign(form,{ doctorId:'', scheduleDate:new Date().toISOString().split('T')[0], startTime:'08:00', endTime:'12:00', quota:20, isActive:true }); activeId.value=''; editMode.value='create' }
function openCreate(){ errorMessage.value=''; successMessage.value=''; resetForm(); modalOpen.value=true }
function openEdit(row: ScheduleRow){ errorMessage.value=''; successMessage.value=''; editMode.value='edit'; activeId.value=row.id; Object.assign(form,{ doctorId:row.doctorId, scheduleDate:row.scheduleDate.split('T')[0], startTime:row.startTime, endTime:row.endTime, quota:row.quota, isActive:row.isActive }); modalOpen.value=true }
async function handleSubmit(){ errorMessage.value=''; successMessage.value=''; if(!form.doctorId||!form.scheduleDate||!form.startTime||!form.endTime){ errorMessage.value='Dokter, tanggal, jam mulai, dan jam selesai wajib diisi'; return } saving.value=true; try { if(editMode.value==='edit'&&activeId.value){ await $fetch(`/api/admin/schedules/${activeId.value}`, { method:'PATCH', body:{ ...form } }); successMessage.value='Jadwal berhasil diperbarui' } else { await $fetch('/api/admin/schedules', { method:'POST', body:{ ...form } }); successMessage.value='Jadwal berhasil ditambahkan' } modalOpen.value=false; resetForm(); await refresh() } catch (error:any) { errorMessage.value=error?.data?.statusMessage || error?.message || 'Gagal menyimpan jadwal' } finally { saving.value=false } }
async function handleDelete(row: ScheduleRow){ errorMessage.value=''; successMessage.value=''; deletingId.value=row.id; try { await $fetch(`/api/admin/schedules/${row.id}`, { method:'DELETE' }); successMessage.value='Jadwal dinonaktifkan'; await refresh() } catch (error:any) { errorMessage.value=error?.data?.statusMessage || error?.message || 'Gagal menghapus jadwal' } finally { deletingId.value='' } }
</script>
<template><div class="admin-page"><div class="flex flex-col gap-4 lg:flex-row lg:items-start lg:justify-between"><div><h1 class="text-4xl font-semibold tracking-tight">Jadwal Dokter</h1><p class="mt-2 text-lg text-muted">Jadwal aktif dokter dari backend admin.</p></div><div class="flex gap-3"><UButton label="Muat Ulang" icon="i-lucide-refresh-cw" color="neutral" variant="outline" :loading="pending" @click="refresh" /><UButton label="Tambah Jadwal" icon="i-lucide-plus" color="primary" @click="openCreate" /></div></div><UPageCard class="admin-table-card"><UFormField label="Filter Dokter"><USelectMenu v-model="selectedDoctorId" value-key="value" option-attribute="label" :items="[{ label: 'Semua Dokter', value: '' }, ...doctorOptions]" /></UFormField></UPageCard><UPageCard v-if="successMessage" class="admin-table-card border border-success/30"><p class="font-semibold text-success">{{ successMessage }}</p></UPageCard><UPageCard v-if="error || errorMessage" class="admin-table-card border border-error/30"><p class="font-semibold text-error">{{ errorMessage || 'Gagal memuat jadwal.' }}</p></UPageCard><UPageCard class="admin-table-card"><div class="admin-mobile-table overflow-x-auto"><table class="min-w-full text-sm"><thead class="bg-elevated/50 text-left text-muted"><tr><th class="px-6 py-4 font-medium">Dokter</th><th class="px-6 py-4 font-medium">Tanggal</th><th class="px-6 py-4 font-medium">Jam</th><th class="px-6 py-4 font-medium">Kuota</th><th class="px-6 py-4 font-medium">Status</th><th class="px-6 py-4 text-right font-medium">Aksi</th></tr></thead><tbody><tr v-if="!pending && filteredRows.length === 0" class="border-t border-default/70"><td colspan="6" class="px-6 py-8 text-center text-muted">Belum ada jadwal.</td></tr><tr v-for="row in filteredRows" :key="row.id" class="border-t border-default/70"><td class="px-6 py-4" data-label="Dokter"><p class="font-semibold">{{ row.doctor?.fullName || '-' }}</p><p class="text-xs text-muted">{{ row.doctor?.specialization || '-' }}</p></td><td class="px-6 py-4" data-label="Tanggal">{{ formatDate(row.scheduleDate) }}</td><td class="px-6 py-4" data-label="Jam">{{ row.startTime }} - {{ row.endTime }}</td><td class="px-6 py-4" data-label="Kuota">{{ row.quota }}</td><td class="px-6 py-4" data-label="Status"><UBadge :color="row.isActive ? 'success' : 'neutral'" variant="subtle">{{ row.isActive ? 'aktif' : 'nonaktif' }}</UBadge></td><td class="px-6 py-4" data-label="Aksi"><div class="flex justify-end gap-2"><UButton icon="i-lucide-pencil" color="neutral" variant="ghost" @click="openEdit(row)" /><UButton icon="i-lucide-trash-2" color="error" variant="ghost" :loading="deletingId === row.id" @click="handleDelete(row)" /></div></td></tr></tbody></table></div></UPageCard><UModal v-model:open="modalOpen" :title="editMode === 'edit' ? 'Edit Jadwal' : 'Tambah Jadwal'"><template #body><div class="space-y-4"><div v-if="errorMessage" class="rounded-2xl border border-error/30 bg-error/5 px-4 py-3 text-sm text-error">{{ errorMessage }}</div><div class="grid gap-4 md:grid-cols-2"><UFormField label="Dokter" required><USelectMenu v-model="form.doctorId" value-key="value" option-attribute="label" :items="doctorOptions" /></UFormField><UFormField label="Tanggal" required><UInput v-model="form.scheduleDate" type="date" /></UFormField><UFormField label="Jam Mulai" required><UInput v-model="form.startTime" type="time" /></UFormField><UFormField label="Jam Selesai" required><UInput v-model="form.endTime" type="time" /></UFormField><UFormField class="md:col-span-2" label="Kuota"><UInput v-model="form.quota" type="number" /></UFormField></div></div></template><template #footer><div class="flex flex-col-reverse gap-3 sm:flex-row sm:justify-end"><UButton label="Batal" color="neutral" variant="ghost" @click="modalOpen = false" /><UButton :label="editMode === 'edit' ? 'Update' : 'Simpan'" icon="i-lucide-save" :loading="saving" @click="handleSubmit" /></div></template></UModal></div></template>
<style scoped>
@media (max-width: 767px) {
  .admin-mobile-table table thead { display:none; }
  .admin-mobile-table table, .admin-mobile-table tbody, .admin-mobile-table tr, .admin-mobile-table td { display:block; width:100%; }
  .admin-mobile-table tr { margin-bottom:1rem; overflow:hidden; border:1px solid rgb(226 232 240); border-radius:1rem; background:white; }
  .admin-mobile-table td { padding:.875rem 1rem; border-bottom:1px solid rgb(241 245 249); }
  .admin-mobile-table td:last-child { border-bottom:none; }
  .admin-mobile-table td::before { content: attr(data-label); display:block; margin-bottom:.35rem; font-size:.7rem; font-weight:700; letter-spacing:.08em; text-transform:uppercase; color:rgb(100 116 139); }
  .admin-mobile-table td .flex.justify-end { justify-content:stretch; flex-wrap:wrap; }
  .admin-mobile-table td .flex.justify-end > * { flex:1 1 0%; }
}
</style>
